import Dexie, { type EntityTable } from 'dexie';
import dexieCloud from 'dexie-cloud-addon';

export interface Product {
  id: string;
  barcode: string;
  name: string;
  price: number; // in centavos
  cost: number; // in centavos
  stock: number;
  category?: string;
  image?: string;
  isQuickTap?: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface TransactionItem {
  productId: string;
  barcode: string;
  name: string;
  price: number;
  quantity: number;
}

export interface Transaction {
  id: string;
  items: TransactionItem[];
  total: number; // in centavos (after discount)
  cashTendered: number;
  change: number;
  createdAt: Date;
  voided?: boolean;
  discount?: { type: 'percent' | 'fixed'; value: number } | null;
  // Absent means a normal cash sale. 'utang' marks a sale recorded on credit,
  // which also has a matching record in the `utang` table tracking the balance.
  paymentType?: 'cash' | 'utang';
}

export interface Customer {
  id: string;
  name: string;
  phone?: string;
  note?: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface Utang {
  id: string;
  customerId: string;
  // The sale this debt came from, so voiding the sale can find (and block on)
  // the debt and its payments.
  transactionId?: string;
  items: TransactionItem[];
  total: number; // in centavos (after discount)
  createdBy: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface UtangPayment {
  id: string;
  utangId: string;
  amount: number; // in centavos
  note?: string;
  createdBy: string;
  createdAt: Date;
}

// --- Build-time sync config -------------------------------------------------
// Vite inlines import.meta.env at BUILD time, so a value coming from .env must exist
// when the bundle is compiled. The env var wins when present; the constant is the
// fallback. Same pattern as the barcode-inventory app, where a missing env var on CI
// silently folded `if (syncUrl)` to false and disabled sync entirely.
//
// This is tindahan-pos's OWN database. It previously shared barcode-inventory's
// (zo7vbabeq), whose `products` table is keyed by `productId` while this app keys it
// by `id`. Dexie Cloud refuses to change the primary key of an existing table, so
// every sync was rejected with 422 Unprocessable Content — the same failure
// barcode-inventory hit and fixed on its side (commit 655dc47, "rename the catalog
// table to products, unbreaking Dexie Cloud sync"). Point this at a fresh database
// rather than a table another app has already registered.
const DEFAULT_SYNC_URL = 'https://z1n6s3n1x.dexie.cloud';

// The env var is an optional override only; DEFAULT_SYNC_URL below is the real default
// and is correct as committed, so a missing env var is not worth logging about.
const env = import.meta.env;
const syncUrl =
  (env.VITE_DEXIE_CLOUD_SYNC_URL as string | undefined)?.trim() || DEFAULT_SYNC_URL;

/**
 * Test-only escape hatch for the Playwright suite.
 *
 * A real Dexie Cloud sign-in cannot be automated: the one-time code is emailed, so no
 * test can complete it. The authenticated specs therefore seed `tindahan_auth` and load
 * the app with `?e2e=1`, which lets AuthGate render the main app from the seeded role
 * instead of the cloud session.
 *
 * Guarded on `import.meta.env.DEV`, which Vite replaces with `false` in production
 * builds, so the branch is dead-code-eliminated there.
 */
export const E2E_MODE =
  import.meta.env.DEV &&
  typeof window !== 'undefined' &&
  new URLSearchParams(window.location.search).has('e2e');

const db = new Dexie('TindahanPOS', { addons: [dexieCloud] }) as Dexie & {
  products: EntityTable<Product, 'id'>;
  transactions: EntityTable<Transaction, 'id'>;
  customers: EntityTable<Customer, 'id'>;
  utang: EntityTable<Utang, 'id'>;
  utang_payments: EntityTable<UtangPayment, 'id'>;
};

// Declare the schema BEFORE configure(), the same order the working barcode-inventory
// app uses. Dexie applies db.version().stores() to the instance either way, but keeping
// the proven order means one less difference to reason about when sync.
db.version(1).stores({
  products: 'id, barcode, name, category, createdAt',
  transactions: 'id, createdAt',
});

// v2 adds the utang (credit) tables. Adding tables is additive, which Dexie Cloud
// accepts on a live database; renaming or re-keying an existing table is not.
db.version(2).stores({
  products: 'id, barcode, name, category, createdAt',
  transactions: 'id, createdAt',
  customers: 'id, name, createdAt',
  utang: 'id, customerId, createdAt',
  utang_payments: 'id, utangId, createdAt',
});

// v3 indexes utang.transactionId so a sale can find its debt without scanning
// the whole table.
db.version(3).stores({
  products: 'id, barcode, name, category, createdAt',
  transactions: 'id, createdAt',
  customers: 'id, name, createdAt',
  utang: 'id, customerId, transactionId, createdAt',
  utang_payments: 'id, utangId, createdAt',
});

try {
  if (db.cloud) {
    db.cloud.configure({
      databaseUrl: syncUrl,
      // Deliberately NOT requireAuth:true. With it, the addon starts its own login
      // prompt from Dexie's `ready` handler as soon as the database opens — before the
      // user can touch the role picker, so a first-time user could only ever be a
      // cashier (there is no role switcher elsewhere in the app). Auth is gated in
      // React instead (AuthGate in App.tsx): db.cloud.currentUser drives it, and
      // `cloudLogin()` starts the OTP flow from the Sign In button, after the role is
      // known. See https://dexie.org/docs/cloud/dexie-cloud-addon
      requireAuth: false,
      // The app renders the login prompts itself from db.cloud.userInteraction (see
      // components/UserInteractionPrompt.tsx) so they carry this app's styling. Without
      // this the addon injects its own generic dialog on top of the UI.
      customLoginGui: true,
    });
  } else {
    console.warn('[dexie] Dexie Cloud addon not initialized — sync disabled');
  }
} catch (err) {
  console.error('[dexie] Failed to configure Dexie Cloud:', err);
}

export { db };

export function generateId(): string {
  return crypto.randomUUID();
}

export function toCentavos(peso: number): number {
  return Math.round(peso * 100);
}

export function fromCentavos(centavos: number): number {
  return centavos / 100;
}

export function formatPeso(centavos: number): string {
  return '₱' + fromCentavos(centavos).toFixed(2);
}

